parameters.jsCode:
// Normalización y validación inicial
const body = items[0].json.body;

// Mapeo de fuentes según PROMPT_MAESTRO v6.1
let source_system = body.source_system || 'manual';
let source_channel = body.source_channel || 'other';
let connector_name = body.connector_name || 'manual:intake';
let source_detail = body.source_detail || 'n8n_unified_intake';

// Clasificación simple
const text = (body.notes || '') + (body.property_interest || '');
let classification = 'Unknown';
if (/sell|propietario|vender|valoraci|owner/i.test(text)) classification = 'Seller';
else if (/buy|comprar|inversi|search|busco/i.test(text)) classification = 'Buyer';
if (/luxury|premium|hnwi|family office|off-market/i.test(text)) classification = 'HNWI';

// Scoring sugerido
let score = 0;
if (body.budget > 1000000) score += 40;
else if (body.budget > 500000) score += 20;
if (classification === 'HNWI') score += 30;
if (body.gdpr_consent) score += 10;

let tier = 'cold';
if (score >= 70) tier = 'hot';
else if (score >= 40) tier = 'warm';

return [{
  json: {
    org_id: body.org_id || "9d6cb56d-3f21-4f7b-80ea-797a7c2c62cf",
    external_id: body.external_id || body.email || `lead-${Date.now()}`,
    connector_name: connector_name,
    source_system: source_system,
    source_channel: source_channel,
    source_detail: source_detail,
    gdpr_consent: body.gdpr_consent || false,
    name: body.name || 'Anonymous Lead',
    email: body.email,
    phone: body.phone,
    budget: body.budget,
    property_interest: body.property_interest,
    notes: body.notes,
    qualification_score: score,
    qualification_tier: tier,
    metadata: {
      ...body.metadata,
      classification: classification,
      workflow: 'n8n-unified-lead-intake',
      captured_at_n8n: new Date().toISOString()
    }
  }
}];

